CREATE TABLE "app_settings" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("key"));
CREATE TABLE "auftragsbestand_artikel" ("artikelnummer" TEXT NOT NULL, "bezeichnung" TEXT NOT NULL DEFAULT '', "bezeichnung2" TEXT NULL, "lager_kg" REAL NOT NULL DEFAULT 0.0, "auftrag_kg" REAL NOT NULL DEFAULT 0.0, "auftrag_menge" REAL NULL, "auftrag_einheit" TEXT NULL, "bericht_stand" INTEGER NULL, "zeitraum_von" INTEGER NULL, "zeitraum_bis" INTEGER NULL, "importiert_am" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("artikelnummer"));
CREATE TABLE "auftragsbestand_artikel_vorher" ("artikelnummer" TEXT NOT NULL, "bezeichnung" TEXT NOT NULL DEFAULT '', "bezeichnung2" TEXT NULL, "lager_kg" REAL NOT NULL DEFAULT 0.0, "auftrag_kg" REAL NOT NULL DEFAULT 0.0, "auftrag_menge" REAL NULL, "auftrag_einheit" TEXT NULL, "bericht_stand" INTEGER NULL, "zeitraum_von" INTEGER NULL, "zeitraum_bis" INTEGER NULL, "importiert_am" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("artikelnummer"));
CREATE TABLE "auftragsbestand_positionen" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "artikelnummer" TEXT NOT NULL, "beleg" TEXT NOT NULL, "debitor" TEXT NOT NULL DEFAULT '', "warenausgang" INTEGER NOT NULL, "lieferdatum" INTEGER NULL, "menge" REAL NOT NULL DEFAULT 0.0, "einheit" TEXT NULL, "kg" REAL NOT NULL DEFAULT 0.0);
CREATE TABLE "auftragsbestand_positionen_vorher" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "artikelnummer" TEXT NOT NULL, "beleg" TEXT NOT NULL, "debitor" TEXT NOT NULL DEFAULT '', "warenausgang" INTEGER NOT NULL, "lieferdatum" INTEGER NULL, "menge" REAL NOT NULL DEFAULT 0.0, "einheit" TEXT NULL, "kg" REAL NOT NULL DEFAULT 0.0);
CREATE TABLE "demands" ("id" TEXT NOT NULL, "product_id" TEXT NOT NULL, "menge_kg_fertig" REAL NOT NULL, "termin" INTEGER NULL, "quelle" TEXT NOT NULL DEFAULT 'bestellung', "prioritaet" INTEGER NOT NULL DEFAULT 0, "notizen" TEXT NULL, "auftrags_zeilen" TEXT NULL, "manuell_erledigt" INTEGER NOT NULL DEFAULT 0 CHECK ("manuell_erledigt" IN (0, 1)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "entwicklung_datei_inhalte" ("datei_id" TEXT NOT NULL, "inhalt" BLOB NOT NULL, PRIMARY KEY ("datei_id"));
CREATE TABLE "entwicklung_dateien" ("id" TEXT NOT NULL, "projekt_id" TEXT NULL, "name" TEXT NOT NULL, "mime_typ" TEXT NULL, "groesse" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "pruefsumme" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "entwicklung_fliessdiagramme" ("id" TEXT NOT NULL, "bezeichnung" TEXT NOT NULL, "sortierung" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "entwicklung_gesamtprojekte" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "kunde" TEXT NULL, "anfrage" TEXT NULL, "notizen" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "entwicklung_projekt_eintraege" ("id" TEXT NOT NULL, "projekt_id" TEXT NOT NULL, "art" TEXT NOT NULL, "titel" TEXT NOT NULL, "datum" INTEGER NOT NULL, "benutzer" TEXT NULL, "beschreibung" TEXT NULL, "status" TEXT NOT NULL DEFAULT 'offen', "wert" TEXT NULL, "ziel" TEXT NULL, "aenderungen" TEXT NULL, "datei_id" TEXT NULL, "version_id" TEXT NULL, "kommentare" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "entwicklung_projekte" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "kunde" TEXT NULL, "artikelnummer" TEXT NULL, "status" TEXT NOT NULL DEFAULT 'entwicklung', "produktidee" TEXT NULL, "kundenvereinbarungen" TEXT NULL, "fliessdiagramm" TEXT NULL, "neuer_prozess" INTEGER NOT NULL DEFAULT 0 CHECK ("neuer_prozess" IN (0, 1)), "neue_zutaten" INTEGER NOT NULL DEFAULT 0 CHECK ("neue_zutaten" IN (0, 1)), "neue_zutaten_details" TEXT NULL, "ziel_fett" REAL NULL, "ziel_eiweiss" REAL NULL, "grenze_aw" REAL NULL, "notizen" TEXT NULL, "bild_datei_id" TEXT NULL, "sensorik" TEXT NULL, "checkliste" TEXT NULL, "etikett_checkliste" TEXT NULL, "prozess" TEXT NULL, "prozess_historie" TEXT NULL, "haccp" TEXT NULL, "spezifikation" TEXT NULL, "gesamtprojekt_id" TEXT NULL, "artikel_id" TEXT NULL, "freigabe_version_id" TEXT NULL, "freigegeben_am" INTEGER NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "entwicklung_rezeptur_positionen" ("id" TEXT NOT NULL, "version_id" TEXT NOT NULL, "reihenfolge" INTEGER NOT NULL DEFAULT 0, "zutat_id" TEXT NULL, "unterrezeptur_id" TEXT NULL, "unter_version_id" TEXT NULL, "menge_kg" REAL NOT NULL DEFAULT 0.0, "quid_pflicht" INTEGER NULL CHECK ("quid_pflicht" IN (0, 1)), "etikett_name" TEXT NULL, "notiz" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "entwicklung_rezeptur_versionen" ("id" TEXT NOT NULL, "rezeptur_id" TEXT NOT NULL, "nummer" INTEGER NOT NULL, "bezeichnung" TEXT NULL, "status" TEXT NOT NULL DEFAULT 'entwurf', "verlust_prozent" REAL NOT NULL DEFAULT 0.0, "fett_verlust_prozent" REAL NOT NULL DEFAULT 0.0, "verlust_art" TEXT NOT NULL DEFAULT 'trocknung', "notiz" TEXT NULL, "stand" TEXT NULL, "abgeschlossen_am" INTEGER NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "entwicklung_rezepturen" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "artikelnummer" TEXT NULL, "beschreibung" TEXT NULL, "projekt_id" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "entwicklung_zutaten" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "artikelnummer" TEXT NULL, "etikett_name" TEXT NULL, "ist_fleisch" INTEGER NOT NULL DEFAULT 0 CHECK ("ist_fleisch" IN (0, 1)), "ist_wasser" INTEGER NOT NULL DEFAULT 0 CHECK ("ist_wasser" IN (0, 1)), "tierart" TEXT NULL, "bindegewebe" REAL NULL, "fleischeiweiss_grenze" REAL NULL, "quid_pflicht" INTEGER NOT NULL DEFAULT 0 CHECK ("quid_pflicht" IN (0, 1)), "unterzutaten" TEXT NULL, "verarbeitungshilfsstoffe" TEXT NULL, "allergene" TEXT NULL, "energie_kj" REAL NULL, "energie_kcal" REAL NULL, "fett" REAL NULL, "gesaettigte_fettsaeuren" REAL NULL, "kohlenhydrate" REAL NULL, "zucker" REAL NULL, "eiweiss" REAL NULL, "salz" REAL NULL, "wasser" REAL NULL, "asche" REAL NULL, "beffe" REAL NULL, "notiz" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "machine_parameter_defs" ("id" TEXT NOT NULL, "maschine_id" TEXT NOT NULL, "parameter_name" TEXT NOT NULL, "einheit" TEXT NULL, "sortierung" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, PRIMARY KEY ("id"), UNIQUE ("maschine_id", "parameter_name"));
CREATE TABLE "machines" ("id" TEXT NOT NULL, "name" TEXT NOT NULL UNIQUE, "abteilung" TEXT NOT NULL, "typische_parameter" TEXT NULL, "ist_planungsressource" INTEGER NOT NULL DEFAULT 0 CHECK ("ist_planungsressource" IN (0, 1)), "kapazitaet_minuten_pro_tag" REAL NOT NULL DEFAULT 600.0, "eignung_hinweis" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "order_list_items" ("id" TEXT NOT NULL, "raw_material_id" TEXT NOT NULL REFERENCES raw_materials (id), "woche_start_datum" INTEGER NOT NULL, "benoetigte_menge" REAL NOT NULL, "einheit" TEXT NOT NULL, "bestellt" INTEGER NOT NULL DEFAULT 0 CHECK ("bestellt" IN (0, 1)), "bestellt_am" INTEGER NULL, "geliefert" INTEGER NOT NULL DEFAULT 0 CHECK ("geliefert" IN (0, 1)), "geliefert_am" INTEGER NULL, "notizen" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
