CREATE TABLE "production_runs" ("id" TEXT NOT NULL, "task_id" TEXT NOT NULL REFERENCES production_tasks (id), "tatsaechliche_dauer_minuten" REAL NOT NULL, "tatsaechliche_mitarbeiter" INTEGER NOT NULL, "tatsaechliche_menge_kg" REAL NOT NULL, "verwendete_chargen_json" TEXT NULL, "notizen" TEXT NULL, "erfasst_von" TEXT NULL, "erfasst_am" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "production_tasks" ("id" TEXT NOT NULL, "product_id" TEXT NOT NULL REFERENCES products (id), "menge_kg" REAL NOT NULL, "datum" INTEGER NOT NULL, "abteilung" TEXT NOT NULL, "maschine_id" TEXT NULL, "bedarf_id" TEXT NULL, "fertig_menge_kg" REAL NULL, "auftrags_zeilen" TEXT NULL, "start_zeit" TEXT NULL, "geplante_dauer_minuten" REAL NOT NULL, "geplante_mitarbeiter" INTEGER NOT NULL, "sortierung" INTEGER NOT NULL DEFAULT 0, "status" TEXT NOT NULL DEFAULT 'geplant', "parent_task_id" TEXT NULL, "notizen" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "products" ("id" TEXT NOT NULL, "artikelnummer" TEXT NOT NULL UNIQUE, "artikelbezeichnung" TEXT NOT NULL, "beschreibung" TEXT NULL, "notizen" TEXT NULL, "ist_eingepflegt" INTEGER NOT NULL DEFAULT 1 CHECK ("ist_eingepflegt" IN (0, 1)), "produktgruppe" TEXT NULL, "verpackungsart" TEXT NULL, "gebinde_groesse_kg" REAL NULL, "haltbarkeit_tage" INTEGER NULL, "gesamt_ausbeute_faktor" REAL NULL, "mindest_vorlaufzeit_tage" INTEGER NULL, "planungsgruppe" TEXT NULL, "ziel_kerntemp_c" REAL NULL, "kutter_endtemp_c" REAL NULL, "braet_feinheit" TEXT NULL, "kochkammer_programm" TEXT NULL, "raeucherart" TEXT NULL, "startkultur" TEXT NULL, "reifezeit_tage" INTEGER NULL, "klimaprogramm" TEXT NULL, "ziel_ph" REAL NULL, "ziel_aw" REAL NULL, "gewichtsverlust_prozent" REAL NULL, "poekelart" TEXT NULL, "lake_konzentration_prozent" REAL NULL, "poekelzeit_tage" INTEGER NULL, "tumbelzeit_min" REAL NULL, "basis_produkt_artikelnummer" TEXT NULL, "scheibendicke_mm" REAL NULL, "scheiben_pro_packung" INTEGER NULL, "packungsgewicht_g" REAL NULL, "map_gas" TEXT NULL, "formgewicht_g" REAL NULL, "form" TEXT NULL, "bratgrad" TEXT NULL, "panierart" TEXT NULL, "panier_aufnahme_prozent" REAL NULL, "fleischanteil_typ" TEXT NULL, "gesamtdurchlaufzeit_max_std" REAL NULL, "wolf_lochscheibe_mm" REAL NULL, "abkuehlgradient" TEXT NULL, "braten_variante" TEXT NULL, "fuellung" TEXT NULL, "netzbindung" INTEGER NULL CHECK ("netzbindung" IN (0, 1)), "sv_badtemp_c" REAL NULL, "sv_garzeit_std" REAL NULL, "anbratgrad" TEXT NULL, "allergene" TEXT NULL, "qualitaetsstufe" TEXT NULL, "verarbeitungsstufe" TEXT NULL, "verpackungsformen" TEXT NULL, "karton_groesse" TEXT NULL, "karton_bedruckung" TEXT NULL, "packungen_pro_karton" INTEGER NULL, "fuellmenge_netto_g" REAL NULL, "abgabeart" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "raw_material_batches" ("id" TEXT NOT NULL, "raw_material_id" TEXT NOT NULL REFERENCES raw_materials (id), "chargennummer" TEXT NOT NULL, "mhd" INTEGER NULL, "eingangs_datum" INTEGER NOT NULL, "menge_initial" REAL NOT NULL, "menge_aktuell" REAL NOT NULL, "einheit" TEXT NOT NULL, "lieferant" TEXT NULL, "notizen" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "raw_materials" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "artikelnummer" TEXT NULL, "einheit" TEXT NOT NULL, "lieferant" TEXT NULL, "lead_time_tage" INTEGER NULL, "chargen_pflicht" INTEGER NOT NULL DEFAULT 1 CHECK ("chargen_pflicht" IN (0, 1)), "notizen" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "tagesaufgaben" ("id" TEXT NOT NULL, "datum" INTEGER NOT NULL, "abteilung" TEXT NOT NULL, "inhalt" TEXT NOT NULL, "erledigt" INTEGER NOT NULL DEFAULT 0 CHECK ("erledigt" IN (0, 1)), "sortierung" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "task_dependencies" ("id" TEXT NOT NULL, "from_task_id" TEXT NOT NULL REFERENCES production_tasks (id), "to_task_id" TEXT NOT NULL REFERENCES production_tasks (id), "typ" TEXT NOT NULL DEFAULT 'finish_to_start', "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "week_snapshots" ("id" TEXT NOT NULL, "wochen_start" INTEGER NOT NULL, "kw" INTEGER NOT NULL, "jahr" INTEGER NOT NULL, "titel" TEXT NULL, "notiz" TEXT NULL, "daten_json" TEXT NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "zusatzzeiten" ("id" TEXT NOT NULL, "datum" INTEGER NOT NULL, "spur_id" TEXT NOT NULL, "art" TEXT NOT NULL, "minuten" REAL NOT NULL, "notiz" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE INDEX idx_batches_raw_material_id ON raw_material_batches(raw_material_id);
CREATE INDEX idx_machines_abteilung ON machines(abteilung);
CREATE INDEX idx_machines_name ON machines(name);
CREATE INDEX idx_order_list_woche ON order_list_items(woche_start_datum);
CREATE INDEX idx_product_steps_product_id ON product_steps(product_id, reihenfolge);
CREATE INDEX idx_production_history_product ON production_history(product_id, datum);
CREATE INDEX idx_production_runs_task_id ON production_runs(task_id);
CREATE INDEX idx_production_tasks_datum_abteilung ON production_tasks(datum, abteilung);
CREATE INDEX idx_products_artikelnummer ON products(artikelnummer);
CREATE INDEX idx_products_produktgruppe ON products(produktgruppe);
CREATE INDEX idx_step_params_name ON product_step_parameters(parameter_name);
CREATE INDEX idx_step_params_step_id ON product_step_parameters(step_id, reihenfolge);
CREATE TRIGGER trg_schritt_macht_eingepflegt AFTER INSERT ON product_steps BEGIN UPDATE products SET ist_eingepflegt = 1 WHERE id = NEW.product_id AND ist_eingepflegt = 0; END;
